--
-- Dumping data for table `faqs`
--

LOCK TABLES `faqs` WRITE;
/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT INTO `faqs` VALUES (2,1,1,'How do I place an order on BillMintMall?','Browse our products, add the items you want to your cart, and proceed to checkout. You can pay using any of our supported payment methods. Once your order is placed, you will receive a confirmation email with your order details.',1,'how-do-i-place-an-order-on-billmintmall',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(3,1,1,'How can I track my order?','After your order is shipped, you will receive a tracking ID by email. You can also track your order anytime from your account by going to \"My Orders\" on the customer dashboard.',2,'how-can-i-track-my-order',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(4,1,1,'How long does delivery take?','Standard delivery typically takes 3-7 business days, depending on your location. Express delivery (where available) usually arrives within 1-3 business days. Exact delivery times are shown on each product page and at checkout.',3,'how-long-does-delivery-take',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(5,1,1,'What payment methods do you accept?','We accept Credit/Debit Cards, UPI, Net Banking, Wallets, and Cash on Delivery (COD) for eligible orders. All online payments are processed through secure payment gateways.',4,'what-payment-methods-do-you-accept',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(6,1,1,'What is your return and refund policy?','Most products can be returned within 7 days of delivery if they are unused, in original packaging, and in resalable condition. Refunds are processed within 5-7 business days after we receive and inspect the returned item. Some categories (like personal care or innerwear) may not be eligible for return.',5,'what-is-your-return-and-refund-policy',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(7,1,1,'How do I cancel my order?','You can cancel your order before it is shipped from your account under \"My Orders\". Once an order has been shipped, it cannot be cancelled but you may return it after delivery as per our return policy.',6,'how-do-i-cancel-my-order',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(8,1,1,'How do I create an account?','Click on \"Customer Login\" at the top of the page and choose \"Register\". Fill in your name, mobile, email, and password. You will receive a 6-digit OTP on your email to verify your account, and you will be logged in automatically after verification.',7,'how-do-i-create-an-account',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(9,1,1,'I forgot my password. How do I reset it?','Click \"Forgot Password?\" on the login page and enter your registered email. You will receive a password reset link by email — open it and follow the instructions to set a new password.',8,'i-forgot-my-password-how-do-i-reset-it',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(10,1,1,'How do I become a seller on BillMintMall?','Click on \"Seller Login\" → \"Register as Seller\" or visit /seller/registration. Fill out your business details (PAN, GSTIN if applicable, address, and shop info) and submit. Our team will review and activate your seller account.',9,'how-do-i-become-a-seller-on-billmintmall',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL),(11,1,1,'How can I contact customer support?','You can reach us by emailing contact@billmintmall.com or calling +91 9211635360. We are available Monday to Saturday, 10 AM to 7 PM IST.',10,'how-can-i-contact-customer-support',1,'2026-05-12 10:16:39','2026-05-12 10:16:39',NULL);
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

