--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `seller_id` bigint unsigned DEFAULT NULL,
  `category_id` bigint unsigned NOT NULL,
  `brand_id` bigint unsigned DEFAULT NULL,
  `name` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tags` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `is_manage_stock` tinyint(1) NOT NULL DEFAULT '1',
  `courieres` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `attributes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `minimum_qty` int NOT NULL,
  `barcode` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sku` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_refundable` tinyint NOT NULL DEFAULT '0',
  `unit_price` double NOT NULL,
  `purchase_price` double DEFAULT NULL,
  `sale_price` double NOT NULL,
  `quantity` int NOT NULL,
  `discount` double DEFAULT NULL,
  `discount_type` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_cost` double DEFAULT '0',
  `outside_shipping_cost` double DEFAULT '0',
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `short_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `specification_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `specification_items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `pdf_specification` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_title` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `meta_image` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_viewed` bigint NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1',
  `publish_stat` int NOT NULL COMMENT '0 = UnPublish, 1= Draft, 2=Published',
  `warranty` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `return_policy` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wholesale_status` int NOT NULL DEFAULT '0' COMMENT '0=Unpublish | 1=Publish',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `products_chk_1` CHECK (json_valid(`specification_items`))
) ENGINE=InnoDB AUTO_INCREMENT=967 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (736,36,1026,NULL,'Men Slim Fit Striped Casual Shirt','Piece',NULL,1,NULL,'null',1,NULL,'MS1',0,1250,1250,1250,120,NULL,'percentage',NULL,NULL,'<blockquote><pre>PRODUCT OVERVIEW<br>────────────────────────────────────────────<br>Premium casual shirt designed for a stylish and modern look. Crafted from high-quality pure cotton fabric for maximum comfort. Soft and breathable material ensures all-day freshness.<br>KEY BENEFITS<br>────────────────────────────────────────────<br>&nbsp; ✔&nbsp; Slim fit design enhances the overall body shape<br>&nbsp; ✔&nbsp; Elegant striped pattern adds a trendy touch to your outfit<br>&nbsp; ✔&nbsp; Full sleeve design makes it suitable for multiple occasions<br>&nbsp; ✔&nbsp; Ideal choice for casual outings, office wear, and social gatherings<br>&nbsp; ✔&nbsp; Lightweight fabric provides ease of movement and flexibility<br>&nbsp; ✔&nbsp; Perfect for daily wear as well as weekend styling<br>&nbsp; ✔&nbsp; Classic red color adds vibrancy and boldness to your wardrobe<br>&nbsp; ✔&nbsp; Designed to offer a balance of comfort and sophistication<br>&nbsp; ✔&nbsp; Suitable for all seasons due to breathable cotton fabric<br>&nbsp; ✔&nbsp; Easy to pair with jeans, chinos, or trousers<br>&nbsp; ✔&nbsp; Durable stitching ensures long-lasting wear<br>&nbsp; ✔&nbsp; Designed for men who prefer a smart casual look<br>WHY BUY THIS<br>────────────────────────────────────────────<br>Maintains shape and color even after multiple washes. Comfortable fit for long working hours or travel. Versatile styling option for both day and evening wear.</pre></blockquote>','Premium casual shirt designed for a stylish and modern look. Crafted from high-quality pure cotton fabric for maximum comfort.','','[{\"label\":\"Brand\",\"value\":\"INDIAN TERRAIN\"},{\"label\":\"Product Type\",\"value\":\"Casual Shirt\"},{\"label\":\"Fit Type\",\"value\":\"Slim Fit\"},{\"label\":\"Fabric\",\"value\":\"100% Pure Cotton\"},{\"label\":\"Fabric Type\",\"value\":\"Breathable and Skin-Friendly\"},{\"label\":\"Sleeve Type\",\"value\":\"Full Sleeve\"},{\"label\":\"Pattern\",\"value\":\"Striped Design\"},{\"label\":\"Color\",\"value\":\"Red\"},{\"label\":\"Brand Color\",\"value\":\"Red\"},{\"label\":\"Ideal For\",\"value\":\"Men\"}]',NULL,'men-slim-fit-striped-casual-shirt',NULL,NULL,'men-slim-fit-striped-casual-shirt',138,1,2,NULL,NULL,0,'2026-04-06 07:14:21','2026-09-10 06:21:46',NULL),(737,36,1026,NULL,'Men Solid Polo Neck Cotton Blend Yellow T-Shirt','Piece',NULL,1,NULL,'null',1,NULL,'MS736',0,584,NULL,584,68,NULL,'percentage',NULL,NULL,'<pre><b>Product Overview\r\n</b>Trendy polo neck t-shirt designed for a stylish and modern look. Made from premium pure cotton fabric for superior comfort. Soft and breathable material keeps you fresh all day.\r\n<b>Key Benefits\r\n</b>• Slim fit design enhances body shape and provides a sharp look\r\n• Colorblock pattern adds a bold and fashionable touch\r\n• Polo neck collar offers a smart and semi-casual appearance\r\n• Short sleeve design ensures comfort during warm weather\r\n• Ideal for casual outings, hangouts, and daily wear\r\n• Lightweight fabric allows ease of movement\r\n• Mustard yellow color adds a unique and vibrant style\r\n• Perfect blend of comfort and modern fashion\r\n• Suitable for both casual and semi-casual occasions\r\n• Easy to pair with jeans, chinos, or shorts\r\n• Designed for men who prefer a sleek and trendy outfit\r\n• Durable stitching ensures long-lasting wear<b>\r\nWhy Buy This\r\n</b>Retains color and softness even after multiple washes. Comfortable for all-day wear and travel. A great addition to everyday wardrobe essentials.</pre>','Stylish polo neck t-shirt designed for a clean and modern casual look. Made from high-quality cotton blend fabric for enhanced comfort.',NULL,'[{\"label\":\"Brand\",\"value\":\"INDIAN TERRAIN\"},{\"label\":\"Product Type\",\"value\":\"Polo Neck T-Shirt\"},{\"label\":\"Fit Type\",\"value\":\"Regular Fit\"},{\"label\":\"Fabric\",\"value\":\"Cotton Blend\"},{\"label\":\"Fabric Type\",\"value\":\"Soft and Breathable\"},{\"label\":\"Sleeve Type\",\"value\":\"Half Sleeve\"},{\"label\":\"Neck Type\",\"value\":\"Polo Neck\"},{\"label\":\"Pattern\",\"value\":\"Solid\"},{\"label\":\"Color\",\"value\":\"Yellow\"},{\"label\":\"Brand Color\",\"value\":\"Yellow\"},{\"label\":\"Ideal For\",\"value\":\"Men\"},{\"label\":\"Suitable For\",\"value\":\"Western Wear\"},{\"label\":\"Occasion\",\"value\":\"Casual\"},{\"label\":\"Pack of\",\"value\":\"1 T-Shirt\"},{\"label\":\"Net Quantity\",\"value\":\"1\"},{\"label\":\"Style Code\",\"value\":\"ITFTS00003 SS\"}]',NULL,'men-solid-polo-neck-cotton-blend-yellow-t-shirt',NULL,NULL,'men-solid-polo-neck-cotton-blend-yellow-t-shirt',21,1,2,NULL,NULL,0,'2026-04-07 14:26:52','2026-09-10 08:12:33',NULL),(738,36,1039,NULL,'Women Silk Blend Kurta Pant Dupatta','Piece',NULL,1,NULL,'null',1,NULL,'MS737',0,1424,NULL,1424,29,NULL,NULL,NULL,NULL,'<div><div>PRODUCT OVERVIEW</div><div>Premium Anarkali kurta set designed for a graceful and elegant ethnic look Crafted from high-quality silk blend fabric for a rich and luxurious feel Soft and breathable material ensures all-day comfort</div><div><br></div><div>KEY BENEFITS</div><div>• Beautiful embroidered detailing enhances the traditional appeal</div><div>• Flowy Anarkali silhouette adds a royal and flattering touch</div><div>• Paired with matching pants and dupatta for a complete outfit</div><div>• Inner crepe lining provides smooth draping and comfortable fit</div><div>• Ideal for festive occasions, weddings, and special events</div><div>• Lightweight fabric allows ease of movement</div><div>• Three-quarter sleeve design adds sophistication</div><div>• Stylish V-neck enhances the overall look</div><div>• Designed for modern women who prefer traditional elegance</div><div>• Durable stitching ensures long-lasting wear</div><div>• Maintains color and fabric quality after multiple uses</div><div>• Easy to accessorize with heels and jewelry</div><div>• Brand: MOKOSH</div><div>• Product Type: Kurta Pant Dupatta Set</div><div>• Fit Type: Regular Fit</div><div>• Fabric: Silk Blend</div><div>• Fabric Type: Soft and Luxurious</div><div>• Sleeve Type: 3/4 Sleeve</div><div>• Pattern: Embroidered</div><div>• Color: Purple</div><div>• Brand Color: Purple</div><div>• Ideal For: Women</div><div>• Suitable For: Ethnic Wear</div><div>• Occasion: Festive &amp; Party</div><div>• Kurta Style Type: Anarkali</div><div>• Kurta Length: Calf Length</div><div>• Neck Type: V Neck</div><div>• Bottom Type: Pant</div><div>• Dupatta Included: Yes</div><div>• Pack of: 1 Kurta, 1 Pant, 1 Dupatta</div><div>• Net Quantity: 1 Set</div><div>• Reversible: No</div><div>• Style Code: 474</div><div>• Care Instructions: Hand wash or gentle machine wash</div><div>• Durability: Premium quality fabric and stitching</div><div>• Comfort Level: Soft, breathable, and comfortable</div><div><br></div><div>WHY BUY THIS</div><div>Suitable for all festive seasons Offers a perfect blend of comfort and style Elegant outfit for celebrations and gatherings</div></div>','Premium Anarkali kurta set designed for a graceful and elegant ethnic look Crafted from high-quality silk blend fabric for a rich and luxurious feel Soft and breathable material ensures all-day comfort Beautiful embroidered detailing enhances the traditional appeal',NULL,'[{\"label\":\"Product Type\",\"value\":\"Kurta Pant Dupatta Set\"},{\"label\":\"Fit Type\",\"value\":\"Regular Fit\"},{\"label\":\"Fabric\",\"value\":\"Silk Blend\"},{\"label\":\"Fabric Type\",\"value\":\"Soft and Luxurious\"},{\"label\":\"Sleeve Type\",\"value\":\"3\\/4 Sleeve\"},{\"label\":\"Pattern\",\"value\":\"Embroidered\"},{\"label\":\"Occasion\",\"value\":\"Festive & Party\"},{\"label\":\"Durability\",\"value\":\"Premium quality fabric and stitching\"}]',NULL,'women-silk-blend-kurta-pant-dupatta',NULL,NULL,'women-silk-blend-kurta-pant-dupatta',13,1,2,NULL,NULL,0,'2026-04-07 14:48:09','2026-04-08 11:25:12','2026-04-08 11:25:12'),(739,36,1026,13,'Men Colorblock Polo Neck Pure Cotton Yellow T-Shirt','Piece',NULL,1,NULL,NULL,1,NULL,'MS738',0,899,NULL,899,60,NULL,'fixed',NULL,NULL,'<blockquote><b>Product Overview<br></b>Trendy polo neck t-shirt designed for a stylish and modern look. Made from premium pure cotton fabric for superior comfort. Soft and breathable material keeps you fresh all day.<br><b>Key Benefits<br></b>• Slim fit design enhances body shape and provides a sharp look<br>• Colorblock pattern adds a bold and fashionable touch<br>• Polo neck collar offers a smart and semi-casual appearance<br>• Short sleeve design ensures comfort during warm weather<br>• Ideal for casual outings, hangouts, and daily wear<br>• Lightweight fabric allows ease of movement<br>• Mustard yellow color adds a unique and vibrant style<br>• Perfect blend of comfort and modern fashion<br>• Suitable for both casual and semi-casual occasions<br>• Easy to pair with jeans, chinos, or shorts<br>• Designed for men who prefer a sleek and trendy outfit<br>• Durable stitching ensures long-lasting wear<br><b>Why Buy This<br></b>Retains color and softness even after multiple washes. Comfortable for all-day wear and travel. A great addition to everyday wardrobe essentials.</blockquote>','Trendy polo neck t-shirt designed for a stylish and modern look. Made from premium pure cotton fabric for superior comfort.',NULL,'[{\"label\":\"Brand\",\"value\":\"U.S. POLO ASSN.\"},{\"label\":\"Product Type\",\"value\":\"Polo Neck T-Shirt\"},{\"label\":\"Fit Type\",\"value\":\"Slim Fit\"},{\"label\":\"Fabric\",\"value\":\"100% Pure Cotton\"},{\"label\":\"Fabric Type\",\"value\":\"Soft and Breathable\"},{\"label\":\"Sleeve Type\",\"value\":\"Short Sleeve\"},{\"label\":\"Neck Type\",\"value\":\"Polo Neck\"},{\"label\":\"Pattern\",\"value\":\"Colorblock\"},{\"label\":\"Color\",\"value\":\"Yellow\"},{\"label\":\"Brand Color\",\"value\":\"Mustard\"},{\"label\":\"Ideal For\",\"value\":\"Men\"},{\"label\":\"S